from collections import deque

ordered_nodes = deque([node for node in nodes if not node.incoming_nodes])
visited = set()

while ordered_nodes:
    node = ordered_nodes.popleft()
    if node not in visited:
        visited.add(node)
        ordered_nodes.extend(nextnode for nextnode in node.outgoing_nodes if nextnode not in visited)

return list(visited)
